text:
Show the change in enrollment

enrollment_change &lt;- removal_enrollment |&gt;
   mutate(
    special_education_change = (
      ((x2026_2027 - x2025_2026) / x2025_2026) * 100
    ) |&gt; round_half_up(1)
  ) |&gt; 
  arrange(desc(special_education_change))

enrollment_change

Make Separate Section for NA Rows

na_rows_enrollment &lt;- enrollment_number_10 |&gt;
  filter(
    is.na(x2025_2026) | is.na(x2026_2027)
  )

na_rows_enrollment

Remove NA Rows and Remove old columns

removal_enrollment &lt;- enrollment_number_10 |&gt;
  filter(
    !is.na(x2025_2026),
    !is.na(x2026_2027)
  ) |&gt;
  select(
    campus,
    school_active,
    x2025_2026,
    x2026_2027
  ) 

removal_enrollment
